  let frame = 0;
  const step = (t) => {
    const p = Math.min(1, (t - t0) / COUNT_MS);
    const at = Math.round(from + (to - from) * ease(p));
    set(at);
    displayed.set(key, p < 1 ? at : to);
    if (p < 1) frame = requestAnimationFrame(step);
    else inFlight.delete(key);
  };
