  details.setup[open] > summary { border-color: var(--ink-2); color: var(--ink); }
  .setup-body { position: fixed; top: 52px; right: 20px; z-index: 20; width: min(480px, calc(100vw - 40px));
                max-height: calc(100vh - 72px); overflow: auto;
                background: var(--surface); border: 1px solid var(--border);
                border-radius: 10px; padding: 4px 16px 12px;
                box-shadow: 0 12px 32px color-mix(in srgb, var(--ink) 18%, transparent); }
