  .stars { text-align: center; flex: none; min-width: 26px; }
  .stars .glyph { font-size: 11px; line-height: 1; color: var(--s-yellow); }
  .stars .n { font-size: 12px; color: var(--ink-2); }

  /* CI as a dot with its age under it, in place of a word and a column. */
  .ci-dot { text-align: center; min-width: 42px; }
  .ci-dot .dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%;
